@@ -4,11 +4,16 @@ export type OrdersState = {
   loading: boolean;
   orders?: Order[];
   error?: string;
+  /** 1-based number of the current/last fetch attempt. */
+  attempt?: number;
 };

+export const MAX_ATTEMPTS = 3;
+
 export type OrdersEvent =
   | { type: "fetch" }
   | { type: "loaded"; orders: Order[] }
+  | { type: "retry"; attempt: number }
   | { type: "failed"; message: string };

 export const initialState: OrdersState = { loading: false };
@@ -16,7 +21,9 @@ export const initialState: OrdersState = { loading: false };
 export function reduce(state: OrdersState, event: OrdersEvent): OrdersState {
   switch (event.type) {
     case "fetch":
-      return { ...state, loading: true };
+      return { ...state, loading: true, attempt: 1 };
+    case "retry":
+      return { ...state, loading: true, error: undefined, attempt: event.attempt };
     case "loaded":
       return { ...state, loading: false, orders: event.orders };
     case "failed":
@@ -24,8 +31,16 @@ export function reduce(state: OrdersState, event: OrdersEvent): OrdersState {
   }
 }

+/** True when a failed fetch may be retried (fewer than MAX_ATTEMPTS used). */
+export function canRetry(state: OrdersState): boolean {
+  return (state.attempt ?? 1) < MAX_ATTEMPTS;
+}
+
 export function statusText(state: OrdersState): string {
   if (state.error) return `Couldn't load orders: ${state.error}`;
+  if (state.loading && (state.attempt ?? 1) > 1) {
+    return `Retrying (attempt ${state.attempt} of ${MAX_ATTEMPTS})…`;
+  }
   if (state.loading) return "Loading orders…";
   if (state.orders && state.orders.length === 0) return "No orders yet";
   if (state.orders) return `${state.orders.length} orders`;
