index 5c65d90..225b1fd 100644
--- a/test/orderState.test.ts
+++ b/test/orderState.test.ts
@@ -1,6 +1,6 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
-import { initialState, reduce, statusText } from "../src/orderState.ts";
+import { canRetry, initialState, reduce, statusText } from "../src/orderState.ts";

 test("shows loading while fetching", () => {
   const state = reduce(initialState, { type: "fetch" });
@@ -19,3 +19,16 @@ test("shows the error when the fetch fails", () => {
   const state = reduce(reduce(initialState, { type: "fetch" }), { type: "failed", message: "timeout" });
   assert.equal(statusText(state), "Couldn't load orders: timeout");
 });
+
+test("shows retry progress", () => {
+  const failed = reduce(reduce(initialState, { type: "fetch" }), { type: "failed", message: "x" });
+  const state = reduce(failed, { type: "retry", attempt: 2 });
+  assert.equal(statusText(state), "Retrying (attempt 2 of 3)…");
+});
+
+test("allows at most 3 attempts", () => {
+  const s1 = reduce(initialState, { type: "fetch" });
+  const s3 = reduce(s1, { type: "retry", attempt: 3 });
+  assert.equal(canRetry(s1), true);
+  assert.equal(canRetry(s3), false);
+});

