   loading: boolean;
   orders?: Order[];
   error?: string;
+  /** Set only while a retry is in flight: the attempt number being made (2..MAX_ATTEMPTS). */
+  retryAttempt?: number;
 };

 export type OrdersEvent =
   | { type: "fetch" }
+  | { type: "retry"; attempt: number }
   | { type: "loaded"; orders: Order[] }
   | { type: "failed"; message: string };

+/** Total attempts, including the first. */
+export const MAX_ATTEMPTS = 3;
+
 export const initialState: OrdersState = { loading: false };

 export function reduce(state: OrdersState, event: OrdersEvent): OrdersState {
   switch (event.type) {
     case "fetch":
-      return { ...state, loading: true };
+      return { ...state, loading: true, retryAttempt: undefined };
+    case "retry":
+      return { ...state, loading: true, error: undefined, retryAttempt: event.attempt };
