-      return { ...state, loading: false, orders: event.orders };
+      return { ...state, loading: false, orders: event.orders, retryAttempt: undefined };
     case "failed":
-      return { ...state, loading: false, error: event.message };
+      return { ...state, loading: false, error: event.message, retryAttempt: undefined };
+  }
+}
+
+/** Fetches orders, retrying after a failure up to MAX_ATTEMPTS attempts in total. */
+export async function loadOrders(
+  fetchOrders: () => Promise<Order[]>,
+  dispatch: (event: OrdersEvent) => void,
+): Promise<void> {
+  dispatch({ type: "fetch" });
+  for (let attempt = 1; ; attempt++) {
+    try {
+      dispatch({ type: "loaded", orders: await fetchOrders() });
+      return;
+    } catch (err) {
+      if (attempt >= MAX_ATTEMPTS) {
+        dispatch({ type: "failed", message: err instanceof Error ? err.message : String(err) });
+        return;
+      }
+      dispatch({ type: "retry", attempt: attempt + 1 });
+    }
   }
 }

 export function statusText(state: OrdersState): string {
   if (state.error) return `Couldn't load orders: ${state.error}`;
+  if (state.retryAttempt !== undefined) {
+    return `Retrying (attempt ${state.retryAttempt} of ${MAX_ATTEMPTS})…`;
+  }
   if (state.loading) return "Loading orders…";
   if (state.orders && state.orders.length === 0) return "No orders yet";
   if (state.orders) return `${state.orders.length} orders`;

